  width: 300px;
  height: 200px;
  margin: 20px auto;
  padding: 16px;
}

.sidebar { width: 250px; }
.main    { width: 70%; }
.hero    { height: 100vh; }  /* full viewport height */

/* Center horizontally */
margin: 0 auto;

/* Center both directions with flexbox (modern) */
display: flex;
justify-content: center;
align-items: center;

activities.example:
.row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

teaching.text:
.container {
  display: flex;
  gap: 16px;
}

.stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
}

/* Two columns: sidebar 250px, main fills the rest */
grid-template-columns: 250px 1fr;

/* Four equal columns */
grid-template-columns: repeat(4, 1fr);

/* Auto-fit: responsive columns */
grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));

